) VALUES
  ('SX-HIGHNY-26OCT15-B64.5', 'XEV-STD-CLI-01', 'XLSX-STANDARD', 'BINARY', 'Will the maximum temperature in New York City (Central Park) be 64–65°F on Thu 15 Oct 2026? (2°F brackets + tails)', NULL, '1', '1', '99', '1', '99', NULL, '100000', '250000', 'OPEN', '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00', '2026-10-15 23:59:00+00', '2026-10-15 23:59:00+00', 'Kalshi current rules: The Weather Company (weather.com/kalshi); terms PDF hierarchy: NWS then national met service. SarvaeX: NWS Daily Climate Report (CLI) primary. SarvaeX oracle: automated ingest from Source Agency + independent second-source check; Settlement Committee confirms and publishes notice; 30-min review window before final payout.', 'ADMIN', '{"type":"binary_event","source_workbook":"Contracts.xlsx","worksheet":"1_Standard_Contracts","worksheet_row":40,"pair_id":"STD-CLI-01","leg":"Binary","category":"Climate","subcategory":"Weather – US city daily maximum temperature","region":"Global","original_ticker":"SX-HIGHNY-26OCT15-B64.5","encoding":{"divider":100,"decimals":2,"suffix":"¢"},"workbook":{"reference_platforms":"Kalshi (KXHIGH, 20 cities); Polymarket (Wunderground)","reference_id":"K:KXHIGHNY-26SEP11-B83.5","activity":"5009.53","activity_unit":"contracts (Kalshi, 24h)","best_bid":"0.02","best_ask":"0.03","spread":"1","min_top_size":"53","quote_gate":"REVIEW (0/25 climate rows pass)","expiry":"Last trade 23:59 local on the day","settlement_time":"Next morning, after final daily climate report","structure":"Binary event contract (YES/NO). YES pays 1.00 USDC per contract if the Payout Criterion is met at Expiration, else 0. Price 0.01–0.99 USDC, tick 0.01; fully collateralised (max loss = premium). Mutually exclusive brackets.","payoff_formula":"YES = 1 if recorded max in bracket.","tick_terms":"0.01 USDC","multiplier_terms":"1 USDC","resolution_criteria":"Daily maximum at the named station (Central Park, KNYC) for the local-standard-time climate day (runs 01:00–00:59 during DST).","oracle_source":"Kalshi current rules: The Weather Company (weather.com/kalshi); terms PDF hierarchy: NWS then national met service. SarvaeX: NWS Daily Climate Report (CLI) primary. SarvaeX oracle: automated ingest from Source Agency + independent second-source check; Settlement Committee confirms and publishes notice; 30-min review window before final payout.","fallback":"Kalshi tightened weather rules on 3 Sep 2026 amid manipulation concerns – adopt: inconsistent 6h/24h readings delay settlement for review.","documentation":"Kalshi: https://assets.kalshi.com/contract_terms/GLOBALTEMPERATURE.pdf ; https://help.kalshi.com/en/articles/13823837-weather-markets","hedge_link":"Pairs with SXF-HIGHNY (settles to °F).","liquidity":"Thin books (US$2k–20k/day per city) – template value > liquidity value.","priority":"P2 – template","short_title":"","integrity_flags":"","why_now":"","topic_ref":""}}'::jsonb),
  ('SXF-HIGHNY-26OCT15', 'XEV-STD-CLI-01', 'XLSX-STANDARD', 'SCALAR', NULL, 'Underlying: Official daily maximum temperature (°F), Central Park, 15 Oct 2026.', '1', '1', '500', '1', '500', '1000', '100000', '250000', 'OPEN', '2026-01-01 00:00:00+00', '2026-01-01 00:00:00+00', '2026-10-15 23:59:00+00', '2026-10-15 23:59:00+00', 'NWS CLI. SarvaeX oracle: automated ingest from Source Agency + independent second-source check; Settlement Committee confirms and publishes notice; 30-min review window before final payout.', 'ADMIN', '{"type":"scalar_numeric","source_workbook":"Contracts.xlsx","worksheet":"1_Standard_Contracts","worksheet_row":41,"pair_id":"STD-CLI-01","leg":"Futures","category":"Climate","subcategory":"Weather – US city daily maximum temperature","region":"Global","original_ticker":"SXF-HIGHNY-26OCT15","encoding":{"divider":10,"decimals":1},"workbook":{"reference_platforms":"n/a – new SarvaeX product","reference_id":"n/a – new SarvaeX product","activity":"—","activity_unit":"—","best_bid":"—","best_ask":"—","spread":"—","min_top_size":"—","quote_gate":"","expiry":"23:59 local","settlement_time":"Next morning CLI","structure":"Cash-settled linear event futures. Co-expires with the paired binary and settles to the same Source Agency value at the same Expiration (zero settlement basis). Daily MTM variation margin in USDC; cross-margined with the binary ladder.","payoff_formula":"(FSV − Entry) × US$10 per °F.","tick_terms":"0.1°F = US$1; band ±15°F","multiplier_terms":"US$10 per °F","resolution_criteria":"FSV = official daily max (integer °F).","oracle_source":"NWS CLI. SarvaeX oracle: automated ingest from Source Agency + independent second-source check; Settlement Committee confirms and publishes notice; 30-min review window before final payout.","fallback":"As binary.","documentation":"—","hedge_link":"Delta-1 for bracket strip (classic weather future).","liquidity":"CME weather futures (HDD/CDD) basis.","priority":"P2","short_title":"","integrity_flags":"","why_now":"","topic_ref":""}}'::jsonb),
